// HEAD CFG ENTRY
declare(strict_types=1);

date_default_timezone_set('Europe/Istanbul'); // u can edit this func only.
ob_start();

if (session_status() === PHP_SESSION_NONE) {
    session_start();
}

ini_set('log_errors', '1');
ini_set('error_log', __DIR__ . '/Logs/' . date('Y-m-d_H-i-s') . '.log');

set_error_handler(function($errno, $errstr, $errfile, $errline) {
   $log_message = date('Y-m-d H:i:s') . " | Error: [$errno] $errstr in $errfile on line $errline\n";
   error_log($log_message, 3, __DIR__ . '/Logs/' . date('Y-m-d') . '.log');
   return false;
});

error_reporting(0); // for devs
ini_set('display_errors', '0'); // for devs

header("X-Frame-Options: DENY");
header("X-XSS-Protection: 1; mode=block"); 
header("X-Content-Type-Options: nosniff");
// HEAD CFG END

if (basename(__FILE__) == basename($_SERVER['SCRIPT_FILENAME'])) {
    include __DIR__ . '/web.html';
    exit();
}

if (!file_exists(__DIR__ . '/Logs')) {
    mkdir(__DIR__ . '/Logs', 0755, true);
}

$WebURL = (isset($_SERVER['HTTPS']) ? 'https' : 'http') . '://' . $_SERVER['HTTP_HOST'] . rtrim(dirname($_SERVER['SCRIPT_NAME']), '/');
$AstURL = $WebURL . '/core/pages/assets/';

require_once __DIR__ . '/config.php';
require_once __DIR__ . '/services.php';
require_once __DIR__ . '/SpeXSecV3.php';

